package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Persistent entity types from store/*.go (table-backed structs + key enums)
var entityTypes = []string{
	"Attachment", "IdentityProvider", "Inbox", "InstanceSetting",
	"Memo", "MemoRelation", "MemoShare", "Reaction",
	"User", "UserIdentity", "UserSetting",
	"RowStatus", "Visibility", "Role", "MemoRelationType", "InboxStatus",
}

func main() {
	root := "/bench/repo"
	fset := token.NewFileSet()

	// entity -> set of external packages
	entityPkgs := make(map[string]map[string]bool)
	// entity -> set of file paths
	entityFiles := make(map[string]map[string]bool)

	for _, et := range entityTypes {
		entityPkgs[et] = make(map[string]bool)
		entityFiles[et] = make(map[string]bool)
	}

	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || !strings.HasSuffix(path, ".go") {
			return nil
		}
		// skip store package and generated proto
		if strings.Contains(path, "/store/") || strings.Contains(path, "/proto/gen/") {
			return nil
		}
		rel, _ := filepath.Rel(root, path)
		pkg := packageFromPath(rel)

		f, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			return nil
		}

		content, _ := os.ReadFile(path)
		text := string(content)

		for _, et := range entityTypes {
			// Look for store.Entity or store.Entity{ patterns
			patterns := []string{
				"store." + et,
				"*store." + et,
				"[]store." + et,
				"[]*store." + et,
				"map[" + "]*store." + et,
			}
			found := false
			for _, p := range patterns {
				if strings.Contains(text, p) {
					found = true
					break
				}
			}
			if !found {
				// also check selector expressions via AST
				ast.Inspect(f, func(n ast.Node) bool {
					if sel, ok := n.(*ast.SelectorExpr); ok {
						if x, ok := sel.X.(*ast.Ident); ok && x.Name == "store" && sel.Sel.Name == et {
							found = true
							return false
						}
					}
					return true
				})
			}
			if found {
				entityPkgs[et][pkg] = true
				entityFiles[et][rel] = true
			}
		}
		return nil
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "walk error: %v\n", err)
		os.Exit(1)
	}

	type result struct {
		entity string
		count  int
		pkgs   []string
		files  []string
	}
	var results []result
	for _, et := range entityTypes {
		pkgs := keys(entityPkgs[et])
		files := keys(entityFiles[et])
		if len(pkgs) > 0 {
			results = append(results, result{et, len(pkgs), pkgs, files})
		}
	}
	sort.Slice(results, func(i, j int) bool {
		if results[i].count != results[j].count {
			return results[i].count > results[j].count
		}
		return results[i].entity < results[j].entity
	})

	fmt.Println("=== Persistent entity types (store layer) ===")
	for _, et := range entityTypes {
		fmt.Printf("  %s\n", et)
	}
	fmt.Println()
	fmt.Println("=== Ranked by distinct external package count ===")
	for _, r := range results {
		fmt.Printf("%s: %d packages\n", r.entity, r.count)
		for _, p := range r.pkgs {
			fmt.Printf("  - %s\n", p)
		}
		fmt.Println("  sample files:")
		for i, f := range r.files {
			if i >= 5 {
				fmt.Printf("  ... and %d more\n", len(r.files)-5)
				break
			}
			fmt.Printf("  - %s\n", f)
		}
		fmt.Println()
	}
}

func packageFromPath(rel string) string {
	dir := filepath.Dir(rel)
	return strings.ReplaceAll(dir, string(filepath.Separator), "/")
}

func keys(m map[string]bool) []string {
	var s []string
	for k := range m {
		s = append(s, k)
	}
	sort.Strings(s)
	return s
}
