use strict;
use warnings;
use File::Find;

my @entities = qw(
  Attachment IdentityProvider Inbox InstanceSetting
  Memo MemoRelation MemoShare Reaction
  User UserIdentity UserSetting
  RowStatus Visibility Role MemoRelationType InboxStatus
);

my %entity_pkgs;
my %entity_files;
for my $e (@entities) {
  $entity_pkgs{$e} = {};
  $entity_files{$e} = {};
}

my $root = "/bench/repo";

find({
  wanted => sub {
    return unless /\.go$/;
    my $path = $File::Find::name;
    return if $path =~ m{/store/};
    return if $path =~ m{/proto/gen/};

    open my $fh, "<", $path or return;
    my $content = do { local $/; <$fh> };
    close $fh;

    my $rel = $path;
    $rel =~ s{^\Q$root\E/?}{};
    (my $pkg = $rel) =~ s{/[^/]+$}{};

    for my $e (@entities) {
      next unless $content =~ /\bstore\.\Q$e\E\b/;
      $entity_pkgs{$e}{$pkg} = 1;
      $entity_files{$e}{$rel} = 1;
    }
  },
  no_chdir => 1,
}, $root);

print "=== Ranked by distinct external package count ===\n";
my @sorted = sort {
  my $ca = scalar keys %{$entity_pkgs{$a}};
  my $cb = scalar keys %{$entity_pkgs{$b}};
  $cb <=> $ca || $a cmp $b
} @entities;

for my $e (@sorted) {
  my @pkgs = sort keys %{$entity_pkgs{$e}};
  next unless @pkgs;
  print "$e: ", scalar(@pkgs), " packages\n";
  for my $p (@pkgs) { print "  - $p\n"; }
  print "  files:\n";
  my @files = sort keys %{$entity_files{$e}};
  my $n = @files > 8 ? 8 : @files;
  for my $i (0..$n-1) { print "  - $files[$i]\n"; }
  print "  ... and ", scalar(@files)-$n, " more\n" if @files > 8;
  print "\n";
}
'

